import{_ as o,l as i,o as e,c as s,v as d,p,x as l,d as r,i as _,S as m,b as t}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"门控线性注意力 GLA","description":"","frontmatter":{"title":"门控线性注意力 GLA","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/gated-linear-attention.md","filePath":"llm/gated-linear-attention.md","lastUpdated":1789023840000}'),h={name:"llm/gated-linear-attention.md"};function S(A,a,f,c,u,G){const n=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=d('<h1 id="门控线性注意力-gla" tabindex="-1">门控线性注意力 GLA <a class="header-anchor" href="#门控线性注意力-gla" aria-label="Permalink to &quot;门控线性注意力 GLA&quot;">​</a></h1><div class="epigraph"><p>在线性注意力的状态更新上乘一个数据依赖的遗忘门，得到可并行训练的门控线性 RNN。</p><footer>—— Yang et al., Gated Linear Attention Transformers with Hardware-Efficient Training, ICML 2024</footer></div><p><a href="/llm/state-space-duality">上一课</a>把对角 SSM 与线性注意力对上。<a href="/llm/linear-attention">线性注意力</a> 的状态 \\(S_t=S_{t-1}+\\phi(k_t)v_t^\\top\\) 只有加法，没有遗忘。<a href="/llm/selective-scan">选择性扫描</a> 的 \\(\\overline{A}_t\\) 是遗忘。本课在注意力记号里把门写回来：GLA。它是线性核族里与 Mamba 选择最接近的一支，后课 HGRN、delta rule 再换门的形状与更新规则。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯加性线性注意力状态单调累积，噪声 token 写进去就出不来，长上下文被灌满。SSM 用 \\(\\overline{A}_t\\) 衰减。缺口是：在 \\(S_t\\) 这种矩阵状态上，用向量或标量门做<strong>逐维遗忘</strong>，并保持分块并行（门必须落在结合结构里）。Yang 等人把这层接到 Transformer 块的注意力槽位，FFN 仍在，故名 GLA Transformer。</p><p><a href="/llm/gated-attention">门控注意力</a> 乘在 softmax 输出上，二次复杂度仍在。GLA 的门在线性状态内部，复杂度仍线性。对象不同。</p><p><span class="marginnote"><a href="/llm/retnet">RetNet</a> 用固定衰减 \\(\\gamma\\)，不是数据依赖门。GLA 的门随 \\(x_t\\) 变，更接近 Mamba 的 \\(\\Delta_t\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>矩阵状态</p> \\[S_t=G_t\\odot S_{t-1}+k_t v_t^\\top, \\]<p>\\(G_t=\\sigma(W_g x_t)\\) 广播到 \\(S\\) 的形状（按行、按列或标量，实现各异）。查询读出 \\(o_t=S_t^\\top q_t\\)（或带核特征 \\(\\phi\\)）。\\(G_t\\) 若只依赖 \\(t\\) 而非过去的 \\(S\\)，更新对 \\(S\\) 仍是仿射加逐点缩放，分块扫描仍可用：块内把缩放吸收进转移。</p><p>训练用分块并行形式；推理逐步更新 \\(S\\)，状态大小 \\(\\Theta(d_k d_v)\\) 或按头计。这比 KV 表的 \\(\\Theta(n d)\\) 在长 \\(n\\) 时小，比对角 SSM 的 \\(\\Theta(N)\\) 大——GLA 用矩阵状态换表达力。</p><h3 id="与-ssd-对角通道" tabindex="-1">与 SSD 对角通道 <a class="header-anchor" href="#与-ssd-对角通道" aria-label="Permalink to &quot;与 SSD 对角通道&quot;">​</a></h3><p>对角 SSM 每通道一个标量状态；GLA 每头一份矩阵。对偶仍可写，但生成元更宽，召回上通常强于很窄的对角 SSM，弱于满 softmax。硬件上矩阵状态的扫描对 SRAM 更饿，块宽要更小心。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>遗忘门把「选择」从 SSM 的 \\(\\Delta\\) 翻译成注意力读者熟悉的 \\(G_t\\)。\\(G_t\\approx 0\\) 重置记忆，\\(G_t\\approx 1\\) 长期保持。因为读出是 \\(q^\\top S\\)，保持的是键值外积的加权和，仍是线性检索：不能在状态里做二次匹配。门控改善的是信噪比与有效记忆长度，不是突然获得 softmax 那种竞争。</p><p>多头让不同头学不同遗忘时间尺度，类似 S4 多时间常数，但由数据决定而非只由初始化。</p><p><span class="marginnote">输出侧再加 GLU 式门是另一条通路，常与状态门一起出现。消融时要分开：一个改记忆，一个改写入残差的幅度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>状态是 \\(d\\times d\\) 级时，头数一多，推理状态可以接近中等上下文的 KV。GLA 的胜负手是「\\(n\\) 很大且 \\(d_k\\) 受控」。核特征 \\(\\phi\\) 仍要选，选不好门再强也是一团糊。下一课 HGRN 把状态收回到更 RNN 的分层门，而不是外积矩阵，容量形状又不同。</p>',20)),(e(),p(m,null,{default:l(()=>[_(n,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Xt%5B%22x_t%22%5D%20--%3E%20G%5B%22%E9%81%97%E5%BF%98%E9%97%A8%20G_t%22%5D%0A%20%20Xt%20--%3E%20KV%5B%22k_t%20v_t%20%E5%A4%96%E7%A7%AF%22%5D%0A%20%20St%5B%22S_%7Bt-1%7D%22%5D%20--%3E%20Up%5B%22S_t%20%3D%20G%20%E2%8A%99%20S%20%2B%20kv%22%5D%0A%20%20G%20--%3E%20Up%0A%20%20KV%20--%3E%20Up%0A%20%20Qt%5B%22q_t%22%5D%20--%3E%20Read%5B%22%E8%AF%BB%E5%87%BA%20S%5ET%20q%22%5D%0A%20%20Up%20--%3E%20Read%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t("h2",{id:"小结",tabindex:"-1"},[r("小结 "),t("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=t("ul",null,[t("li",null,"GLA 在线性注意力的矩阵状态上加数据依赖遗忘门，可分块训练、逐步推理。"),t("li",null,"它对应 SSM 选择在注意力记号下的版本，不是 softmax 输出门。"),t("li",null,"状态体积 \\(\\Theta(d_k d_v)\\) 介于对角 SSM 与 KV 表之间。"),t("li",null,"线性读出仍无二次匹配；门控改善信噪，不消除召回上限。"),t("li",null,"出处：Yang et al., ICML 2024。")],-1))])}const k=o(h,[["render",S]]);export{x as __pageData,k as default};
